typedef unsigned int nslSoundId;

struct nslSound {
  char fields[80];
  float minDist;
  float maxDist;
};

struct nslSystem {
  char beforeSoundSlots[22592];
  nslSound soundSlots[196];
  char beforeOn[17120];
  int on;
};

extern nslSystem nsl;
void _nslInitialized() __asm__("_nslInitialized__Fv");
void _nslCheckSoundIdValidity(nslSoundId) __asm__("_nslCheckSoundIdValidity__FUi");

#define NSL_SLOT_MASK 0x3ff
#define NSL_GET_SLOT_FROM_ID(x) ((x) & NSL_SLOT_MASK)
#define ASSERT_NSL_INITIALIZED() _nslInitialized()
#define ASSERT_SOUND_ID_VALID(x) _nslCheckSoundIdValidity(x)

void nslSetSoundRange( nslSoundId soundToSet, float minDist, float maxDist)
{
  if (!nsl.on) return;
  // if a sound uses the global emitter, do we use these?
  ASSERT_NSL_INITIALIZED();
// not needed?    ASSERT_SOURCE_ID_VALID(nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToSet)].mySource);

  ASSERT_SOUND_ID_VALID(soundToSet);
  nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToSet)].minDist = minDist;
  nsl.soundSlots[NSL_GET_SLOT_FROM_ID(soundToSet)].maxDist = maxDist;

}
